import NavLink from "./nav-link";
import { FileText } from 'lucide-react';
import { Button } from "@/components/ui/button";

export default function Header() {
  const isloggedIn = false;
  return (
    <nav className="container flex items-center justify-between py-4 lg:px-8 px-2 mx-auto">
      <div className="flex lg:flex-1">
        <NavLink href="/" className="flex items-center gap-1 lg:gap-2 shrink-0">
          <FileText className="h-6 w-6 text-gray-900 lg:w-8 lg:h-8 hover:rotate-12 transform transition duration-200 ease-in-out" />
          <span className="font-extrabold lg:text-xl text-gray-900">Project</span>
        </NavLink>
      </div>

      <div className="flex lg:justify-center gap-4 lg:gap-12 lg:items-center font-medium">
        <NavLink href="/pricing">Pricing</NavLink>
        {isloggedIn && <NavLink href="/dashboard">Your Summaries</NavLink>}
      </div>

      <div className="flex lg:jutify-end lg:flex-1">
      {isloggedIn ? (
        <div className="flex gap-2 items-center">
          <NavLink href="/upload">Upload a PDF</NavLink>
          <div>Pro</div>
          <Button>Logout</Button>
        </div>) : (

        <div>
          <NavLink href="/#sign-in">Sign-in</NavLink>
        </div>
      )}
      </div>
    </nav>
  );
}